import uuid
from datetime import datetime
from typing import Any, Optional

from pydantic import BaseModel, ConfigDict, Field


class AgentTraceStep(BaseModel):
    """Execution step trace for a single agent within an orchestrated workflow."""

    agent_name: str
    operation: str
    status: str = "completed"
    latency_ms: int = 0
    reasoning_summary: str
    output_summary: Optional[dict[str, Any]] = None

    model_config = ConfigDict(from_attributes=True)


class ActionProposal(BaseModel):
    """Structured action proposal generated by agents requiring review or one-click execution."""

    id: str
    action_type: str
    title: str
    description: str
    target_id: Optional[str] = None
    target_type: Optional[str] = None  # job, company, recruiter, roadmap
    requires_approval: bool = False
    execution_endpoint: Optional[str] = None
    deep_link: Optional[str] = None
    payload: Optional[dict[str, Any]] = None

    model_config = ConfigDict(from_attributes=True)


class CopilotSessionCreateRequest(BaseModel):
    title: Optional[str] = Field(default="Career Strategy Session", max_length=255)
    session_type: str = Field(default="career_strategy", max_length=50)


class CopilotSessionResponse(BaseModel):
    id: uuid.UUID
    user_id: uuid.UUID
    title: str
    session_type: str
    is_active: bool
    context_summary: dict[str, Any] = Field(default_factory=dict)
    message_count: int = 0
    created_at: datetime
    updated_at: datetime

    model_config = ConfigDict(from_attributes=True)


class CopilotMessageCreateRequest(BaseModel):
    content: str = Field(..., min_length=1, max_length=4000)
    target_job_id: Optional[uuid.UUID] = None
    target_company_id: Optional[uuid.UUID] = None


class CopilotMessageResponse(BaseModel):
    id: uuid.UUID
    session_id: uuid.UUID
    role: str
    content: str
    intent: Optional[str] = None
    agent_trace: list[dict[str, Any]] = Field(default_factory=list)
    action_proposals: list[dict[str, Any]] = Field(default_factory=list)
    token_usage: dict[str, Any] = Field(default_factory=dict)
    created_at: datetime

    model_config = ConfigDict(from_attributes=True)


class CopilotSessionDetailResponse(BaseModel):
    session: CopilotSessionResponse
    messages: list[CopilotMessageResponse]
    context_snapshot: dict[str, Any] = Field(default_factory=dict)

    model_config = ConfigDict(from_attributes=True)


class QuickActionRequest(BaseModel):
    action: str = Field(
        ...,
        description=(
            "career_diagnosis, discover_and_match, prepare_application, "
            "interview_coaching, skill_gap_analysis, weekly_action_plan"
        ),
    )
    target_id: Optional[uuid.UUID] = None
    parameters: Optional[dict[str, Any]] = None


class AgentExecutionRecordResponse(BaseModel):
    id: uuid.UUID
    workflow_id: str
    agent_name: str
    operation: str
    status: str
    latency_ms: int
    tokens_used: int
    provider: str
    model_name: Optional[str] = None
    requires_approval: bool
    approval_state: str
    approved_at: Optional[datetime] = None
    input_context_summary: dict[str, Any] = Field(default_factory=dict)
    output_payload: dict[str, Any] = Field(default_factory=dict)
    error_message: Optional[str] = None
    created_at: datetime

    model_config = ConfigDict(from_attributes=True)


class ApprovalActionRequest(BaseModel):
    action: str = Field(..., description="approve, reject")
    notes: Optional[str] = None


class ApprovalActionResponse(BaseModel):
    record_id: uuid.UUID
    status: str
    message: str
    approved_at: Optional[datetime] = None
